Adafruit_BNO08x bno08x;
U8G2_SSD1309_128X64_NONAME0_F_HW_I2C u8g2(U8G2_R0);

float waypointLat = 40.4168, waypointLon = -3.7038;

float headingDeg() {
  sh2_SensorValue_t v;
  if (bno08x.getSensorEvent(&v) && v.sensorId == SH2_ROTATION_VECTOR) {
    float qw=v.un.rotationVector.real, qz=v.un.rotationVector.k;
    return atan2(2.0*qw*qz, 1.0-2.0*qz*qz) * 180.0/PI;
  }
  return -1;
}

void setup() {
  Wire.begin();
  bno08x.begin_I2C();
  bno08x.enableReport(SH2_ROTATION_VECTOR, 20000);
  u8g2.begin();
}

void loop() {
  float heading = headingDeg();
  if (heading >= 0) {
    u8g2.clearBuffer();
    int tapeX = (int)(-heading * 2) % 256; // desplazamiento de la cinta de compas
    u8g2.drawHLine(0, 10, 128);
    u8g2.setCursor(50, 8);
    u8g2.print((int)heading);
    u8g2.print((char)176);
    u8g2.sendBuffer();
  }
  delay(50);
}

