#include <Wire.h>
#include <MPU6050.h>

MPU6050 mpu;
unsigned long freefallStart = 0;
const float G_THRESHOLD = 0.3; // g
const unsigned long FREEFALL_MS = 300;

void setup() {
  Wire.begin();
  mpu.initialize();
  pinMode(9, OUTPUT);  // servo de disparo
  pinMode(10, OUTPUT); // corte de motores
}

void loop() {
  int16_t ax, ay, az;
  mpu.getAcceleration(&ax, &ay, &az);
  float g = sqrt(sq(ax/16384.0) + sq(ay/16384.0) + sq(az/16384.0));

  if (g < G_THRESHOLD) {
    if (freefallStart == 0) freefallStart = millis();
    if (millis() - freefallStart > FREEFALL_MS) {
      digitalWrite(10, HIGH); // corta motores
      deployParachute();
    }
  } else {
    freefallStart = 0;
  }
}

void deployParachute() {
  // mueve el servo para liberar el pasador
  analogWrite(9, 180);
  while (true) delay(1000); // sistema de un solo uso
}

