#include <Wire.h>
#include <QMC5883LCompass.h>

QMC5883LCompass mag;
float Bprev[3] = {0,0,0};
unsigned long tPrev = 0;
const float KGAIN = 5000.0;

void setCoil(int pwmPin, int dirPin, float value) {
  bool dir = value >= 0;
  digitalWrite(dirPin, dir);
  analogWrite(pwmPin, constrain(abs(value), 0, 255));
}

void setup() {
  Wire.begin();
  mag.init();
}

void loop() {
  mag.read();
  float B[3] = {(float)mag.getX(), (float)mag.getY(), (float)mag.getZ()};
  unsigned long tNow = millis();
  float dt = (tNow - tPrev) / 1000.0;
  if (dt > 0) {
    for (int i = 0; i < 3; i++) {
      float Bdot = (B[i] - Bprev[i]) / dt;
      float cmd = -KGAIN * Bdot; // opone la corriente al cambio de campo
      setCoil(3+i, 6+i, cmd);    // pines ilustrativos por eje
      Bprev[i] = B[i];
    }
  }
  tPrev = tNow;
  delay(50);
}

#include <Wire.h>

struct CcsdsPacket {
  uint16_t apid;
  uint16_t seqCount;
  uint16_t length;
  float voltage, current, temperature;
  float pitch, roll;
  uint16_t checksum;
};

uint16_t seqCounter = 0;

uint16_t computeChecksum(uint8_t* data, size_t len) {
  uint16_t sum = 0;
  for (size_t i = 0; i < len; i++) sum += data[i];
  return sum;
}

void sendHousekeeping() {
  CcsdsPacket pkt;
  pkt.apid = 0x123;
  pkt.seqCount = seqCounter++;
  pkt.voltage = readVoltage();
  pkt.current = readCurrent();
  pkt.temperature = readTemp();
  pkt.pitch = readPitch();
  pkt.roll = readRoll();
  pkt.length = sizeof(CcsdsPacket) - sizeof(uint16_t);
  pkt.checksum = computeChecksum((uint8_t*)&pkt, pkt.length);
  loraSendFrame((uint8_t*)&pkt, sizeof(pkt)); // envia por SX1278
}

void loop() {
  sendHousekeeping();
  delay(1000);
}

#include <Arduino.h>

float readChannel(int adcPin) {
  return analogRead(adcPin) * (3.3 / 4095.0);
}

void computeSunVector(float &az, float &el) {
  float vN = readChannel(PA0);
  float vS = readChannel(PA1);
  float vE = readChannel(PA2);
  float vW = readChannel(PA3);

  float ratioNS = (vN - vS) / (vN + vS + 0.001);
  float ratioEW = (vE - vW) / (vE + vW + 0.001);

  az = atan2(ratioEW, ratioNS) * 180.0 / PI;
  el = 90.0 - sqrt(sq(ratioNS) + sq(ratioEW)) * 90.0; // aproximacion lineal
}

void loop() {
  float az, el;
  computeSunVector(az, el);
  delay(200);
}

