float leerAnguloAS5600() {
  Wire.beginTransmission(AS5600_ADDR);
  Wire.write(0x0C); // registro RAW ANGLE
  Wire.endTransmission(false);
  Wire.requestFrom(AS5600_ADDR, 2);
  int raw = (Wire.read() << 8) | Wire.read();
  return raw * 360.0 / 4096.0;
}

