float Kp=2.5, Ki=0.02, Kd=0.15;
float integral=0, anguloPrev=0;

float pidPosicion(float setpoint, float angulo, float dt) {
  float error = setpoint - angulo;
  integral += error * dt;
  float derivada = (angulo - anguloPrev) / dt;
  anguloPrev = angulo;
  float salida = Kp*error + Ki*integral - Kd*derivada;
  return constrain(salida, -255, 255);
}

float angulo=0, Kp=18, Ki=0.5, Kd=0.7, integral=0, errorPrev=0;

float filtroComplementario(float accAngulo, float gyroRate, float dt) {
  angulo = 0.98*(angulo + gyroRate*dt) + 0.02*accAngulo;
  return angulo;
}

int pidBalance(float setpoint, float ang, float dt) {
  float error = setpoint - ang;
  integral += error*dt;
  float d = (error-errorPrev)/dt; errorPrev = error;
  float salida = Kp*error + Ki*integral + Kd*d;
  return constrain((int)salida, -255, 255);
}

