struct PaqueteTelemetria {
  float lat, lon, alt, voltaje;
  uint8_t checksum;
};

uint8_t calcularChecksum(PaqueteTelemetria &p) {
  uint8_t *b = (uint8_t*)&p;
  uint8_t sum = 0;
  for (size_t i=0; i<sizeof(p)-1; i++) sum ^= b[i];
  return sum;
}

void enviarTelemetria(PaqueteTelemetria p) {
  p.checksum = calcularChecksum(p);
  LoRa.beginPacket();
  LoRa.write((uint8_t*)&p, sizeof(p));
  LoRa.endPacket();
}

void driveSenoidal(float angEléctrico, float amplitud, int ejePWM[3]) {
  for (int f=0; f<3; f++) {
    float fase = angEléctrico + f*2.0944; // 120 grados en radianes
    int duty = (int)(amplitud * (0.5 + 0.5*sin(fase)) * 255);
    analogWrite(ejePWM[f], duty);
  }
}

float pidEje(float setpoint, float angMedido, float &integral, float &errPrev, float dt, float Kp, float Ki, float Kd) {
  float error = setpoint - angMedido;
  integral += error*dt;
  float d = (error-errPrev)/dt; errPrev = error;
  return Kp*error + Ki*integral + Kd*d;
}

