// En el receptor: leer el fotodiodo via comparador digital
// y reconstruir el byte muestreando cada 500us.

#include <arduinoFFT.h>
double vReal[256], vImag[256];
const float F_TX = 10.525e9;
const float C = 3e8;

void computeSpeed() {
  // vReal ya contiene las muestras de audio capturadas
  arduinoFFT FFT = arduinoFFT(vReal, vImag, 256, 4000);
  FFT.Compute(FFT_FORWARD);
  FFT.ComplexToMagnitude();
  int peakIndex = FFT.MajorPeak(&vReal[0], 256, 4000);
  float fBeat = peakIndex; // Hz, aproximado del bin dominante
  float speed_mps = (fBeat * C) / (2 * F_TX);
  updateDisplay(speed_mps);
}

float peakSpeedMph = 0;

