// Pseudocodigo simplificado: se asume que samples[] contiene
// las muestras de IF de un chirp completo
float computeRange(float* samples, int n, float bandwidthHz, float chirpDurationS) {
  // FFT sobre samples[] -> encontrar bin de mayor magnitud (peakBin)
  int peakBin = findFftPeak(samples, n);
  float fBeat = (peakBin * SAMPLE_RATE) / n;
  const float C = 3e8;
  float range_m = (fBeat * C * chirpDurationS) / (2 * bandwidthHz);
  return range_m;
}

// ESP-IDF: callback de CSI simplificado
void wifi_csi_cb(void *ctx, wifi_csi_info_t *info) {
  static float baseline_var = 0;
  static float window[20];
  static int idx = 0;

  int8_t *csi = info->buf;
  float amp_sum = 0;
  for (int i = 0; i < info->len; i += 2) {
    int8_t im = csi[i], re = csi[i+1];
    amp_sum += sqrtf(im*im + re*re);
  }
  float amp_avg = amp_sum / (info->len / 2);

  window[idx % 20] = amp_avg;
  idx++;

  float mean = 0, var = 0;
  for (int i = 0; i < 20; i++) mean += window[i];
  mean /= 20;
  for (int i = 0; i < 20; i++) var += (window[i]-mean)*(window[i]-mean);
  var /= 20;

  if (baseline_var == 0) baseline_var = var; // primera calibración
  if (var > baseline_var * 3.0f) {
    printf("MOVIMIENTO DETECTADO (var=%.3f base=%.3f)\n", var, baseline_var);
  }
