const float L1 = 10.0; // longitud eslabon hombro-codo (cm)
const float L2 = 9.0;  // longitud eslabon codo-muñeca (cm)

struct Angles { float base, shoulder, elbow; bool reachable; };

Angles solveIK(float x, float y, float z) {
  Angles a;
  a.base = atan2(y, x) * 180.0 / PI;

  float r = sqrt(x*x + y*y); // proyección horizontal
  float d = sqrt(r*r + z*z); // distancia directa al objetivo

  if (d > (L1 + L2)) { a.reachable = false; return a; }

  float cosElbow = (L1*L1 + L2*L2 - d*d) / (2*L1*L2);
  a.elbow = acos(constrain(cosElbow, -1.0, 1.0)) * 180.0 / PI;

  float alpha = atan2(z, r);
  float cosBeta = (L1*L1 + d*d - L2*L2) / (2*L1*d);
  float beta = acos(constrain(cosBeta, -1.0, 1.0));
  a.shoulder = (alpha + beta) * 180.0 / PI;

  a.reachable = true;
  return a;
}

