void creepGaitStep(int steppingLeg) {
  // 1. Desplazar el cuerpo para mantener el centro de masa sobre las 3 patas de apoyo
  shiftBodyTowardsSupportPolygon(steppingLeg);

  // 2. Levantar y mover la pata que avanza (swing)
  phase[steppingLeg] = SWING;
  for (float t = 0; t <= 1.0; t += 0.1) {
    float liftZ = sin(t * PI) * 3.0; // trayectoria de arco, 3cm de altura
    moveLegTo(steppingLeg, interpolatedX(t), interpolatedY(t), liftZ);
    delay(20);
  }
  phase[steppingLeg] = STANCE;
}

