volatile long ticksL = 0, ticksR = 0;
const float WHEEL_RADIUS_M = 0.033;
const float WHEEL_BASE_M = 0.15;
const int TICKS_PER_REV = 360;

void isrLeft() { ticksL++; }
void isrRight() { ticksR++; }

float x = 0, y = 0, theta = 0;
long lastTicksL = 0, lastTicksR = 0;

void updateOdometry() {
  long dL = ticksL - lastTicksL;
  long dR = ticksR - lastTicksR;
  lastTicksL = ticksL; lastTicksR = ticksR;
  float distL = (2 * PI * WHEEL_RADIUS_M) * dL / TICKS_PER_REV;
  float distR = (2 * PI * WHEEL_RADIUS_M) * dR / TICKS_PER_REV;
  float dCenter = (distL + distR) / 2.0;
  float dTheta = (distR - distL) / WHEEL_BASE_M;
  x += dCenter * cos(theta + dTheta / 2.0);
  y += dCenter * sin(theta + dTheta / 2.0);
  theta += dTheta;
  // enviar x, y, theta por serie a la Raspberry Pi
}

void setup() {
  Serial.begin(115200);
  attachInterrupt(digitalPinToInterrupt(2), isrLeft, RISING);
  attachInterrupt(digitalPinToInterrupt(3), isrRight, RISING);
}

void loop() {
  updateOdometry();
  Serial.print(x); Serial.print(","); Serial.print(y); Serial.print(","); Serial.println(theta);
  delay(50);
}

