float computePID(float currentTemp) {
  float error = setpoint - currentTemp;
  integral += error;
  float derivative = error - lastError;
  lastError = error;
  float out = Kp * error + Ki * integral + Kd * derivative;
  return constrain(out, 0, 255);
}

