def tokenize(source):
    tokens = []
    i = 0
    while i < len(source):
        c = source[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(source) and source[j].isdigit():
                j += 1
            tokens.append(('NUMBER', source[i:j]))
            i = j
        elif c == '=' and source[i:i+2] == '==':
            tokens.append(('EQ', '=='))
            i += 2
        elif c.isalpha():
            j = i
            while j < len(source) and source[j].isalnum():
                j += 1
            word = source[i:j]
            kind = 'IDENTIFIER' if word not in ('let', 'if', 'function') else word.upper()
            tokens.append((kind, word))
            i = j
        else:
            tokens.append(('OP', c))
            i += 1
    return tokens

const int RELAY_PIN = 25;
float template_[WINDOW];
float buffer_[WINDOW];
unsigned long deviationStart = 0;

float crossCorrelate(float* a, float* b, int n) {
  float num = 0, denA = 0, denB = 0;
  for (int i = 0; i < n; i++) { num += a[i]*b[i]; denA += a[i]*a[i]; denB += b[i]*b[i]; }
  return num / sqrt(denA * denB + 1e-6);
}

void loop() {
  readCurrentWindow(buffer_, WINDOW); // vía INA219 + ADS1115
  float corr = crossCorrelate(buffer_, template_, WINDOW);
  if (corr < CORR_THRESHOLD) {
    if (deviationStart == 0) deviationStart = millis();
    if (millis() - deviationStart > 500) digitalWrite(RELAY_PIN, LOW); // abre el relé
  } else {
    deviationStart = 0;
  }
}

