  float gyro_rate = read_gyro_rate();
  angle = 0.98 * (angle + gyro_rate * dt) + 0.02 * acc_angle; // complementario

  float error = 0 - angle; // objetivo: vertical
  integral += error * dt;
  float derivative = (error - last_error) / dt;
  float output = Kp * error + Ki * integral + Kd * derivative;

  set_motor_speed(output);
  last_error = error;
}

// Emisor: reintento con backoff hasta recibir ACK
const int MAX_RETRIES = 3;
unsigned long backoffMs[] = {1000, 3000, 5000};
byte msgId = 0;

bool sendAndWaitAck(const char* payload) {
  for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
    Serial.print('S'); Serial.print(msgId); Serial.println(payload);
    unsigned long start = millis();
    while (millis() - start < 800) {
      if (Serial.available() && Serial.read() == 'A') {
        digitalWrite(8, HIGH); // LED verde
        return true;
      }
    }
    digitalWrite(9, HIGH); delay(100); digitalWrite(9, LOW); // parpadeo reintento
    delay(backoffMs[attempt]);
  }
  tone(7, 1000, 500); // buzzer: fallo definitivo
  return false;
}

void loop() {
  msgId++;
  sendAndWaitAck("hola");
  delay(10000);
}

