volatile long pulseCount = 0;
float Kp = 2.0, Ki = 5.0, Kd = 0.1;
float integral = 0, lastError = 0;
unsigned long lastTime = 0;

void countPulse() { pulseCount++; }

float computePID(float setpoint, float actualRPM, float dt) {
  float error = setpoint - actualRPM;
  integral += error * dt;
  float derivative = (error - lastError) / dt;
  lastError = error;
  float output = Kp*error + Ki*integral + Kd*derivative;
  return constrain(output, 0, 255);
}

void loop() {
  unsigned long now = millis();
  float dt = (now - lastTime) / 1000.0;
  if (dt >= 0.02) { // 50Hz
    noInterrupts();
    long pulses = pulseCount; pulseCount = 0;
    interrupts();
    float rpm = (pulses / 20.0) * (60.0 / dt);
    float setpoint = analogRead(A0) * (200.0/1023.0); // 0-200 RPM
    float pwmOut = computePID(setpoint, rpm, dt);
    analogWrite(9, (int)pwmOut);
    Serial.print(setpoint); Serial.print(","); Serial.println(rpm);
    lastTime = now;
  }
}

