module clock_divider #(parameter N = 16) (
    input wire clk_in,
    input wire rst,
    output reg clk_out
);
    reg [N-1:0] counter;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            counter <= 0;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == 0) clk_out <= ~clk_out;
        end
    end
endmodule

