}

float Kp=8.0, Ki=0.5, Kd=2.0;
float integral=0, lastError=0;
const float targetTemp = 40.0;

float readTempC(int pin) {
  int raw = analogRead(pin);
  float r = 10000.0 * (1023.0/raw - 1.0); // NTC 10K en divisor
  float steinhart = log(r/10000.0) / 3950.0 + 1.0/298.15;
  return (1.0/steinhart) - 273.15;
}

void loop() {
  float temp = readTempC(A0);
  float error = temp - targetTemp; // más caliente que el objetivo = error positivo
  integral += error;
  float derivative = error - lastError;
  lastError = error;
  int fanPWM = constrain((int)(Kp*error + Ki*integral + Kd*derivative), 0, 255);
  analogWrite(9, fanPWM);
  delay(500);
}

