  delay(500);
}

float angle = 0, bias = 0, P[2][2] = {{1,0},{0,1}};
const float Q_angle = 0.001, Q_bias = 0.003, R_measure = 0.03;

float kalmanUpdate(float newAngle, float newRate, float dt) {
  angle += dt * (newRate - bias);
  P[0][0] += dt * (dt*P[1][1] - P[0][1] - P[1][0] + Q_angle);
  P[0][1] -= dt * P[1][1];
  P[1][0] -= dt * P[1][1];
  P[1][1] += Q_bias * dt;

  float S = P[0][0] + R_measure;
  float K0 = P[0][0] / S, K1 = P[1][0] / S;
  float y = newAngle - angle;
  angle += K0 * y;
  bias  += K1 * y;
  return angle;
}

float pid(float setpoint, float measured, float* integral, float* prevError, float dt) {
  float Kp = 25, Ki = 100, Kd = 0.8;
  float error = setpoint - measured;
  *integral += error * dt;
  float derivative = (error - *prevError) / dt;
  *prevError = error;
  return Kp*error + Ki*(*integral) + Kd*derivative;
}

