Adafruit_BME280 bme;
static osjob_t sendjob;
const unsigned TX_INTERVAL = 600; // segundos

void do_send(osjob_t* j) {
  float t = bme.readTemperature();
  float h = bme.readHumidity();
  int16_t tInt = (int16_t)(t * 100);
  uint8_t payload[4];
  payload[0] = tInt >> 8; payload[1] = tInt;
  payload[2] = (uint8_t)h;
  payload[3] = 0;
  LMIC_setTxData2(1, payload, sizeof(payload), 0);
}

void onEvent(ev_t ev) {
  if (ev == EV_TXCOMPLETE) {
    os_setTimedCallback(&sendjob, os_getTime() + sec2osticks(TX_INTERVAL), do_send);
  }
}

void setup() {
  bme.begin(0x76);
  os_init();
  LMIC_reset();
  do_send(&sendjob);
}

void loop() {
  os_runloop_once();
}

