  IMU.begin();
}

void loop() {
  float buffer[EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE];
  size_t idx = 0;
  while (idx < EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE) {
    float ax, ay, az;
    if (IMU.accelerationAvailable()) {
      IMU.readAcceleration(ax, ay, az);
      buffer[idx++] = ax; buffer[idx++] = ay; buffer[idx++] = az;
    }
  }
  ei_impulse_result_t result;
  signal_t signal;
  numpy::signal_from_buffer(buffer, EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE, &signal);
  run_classifier(&signal, &result, false);
  for (size_t i = 0; i < EI_CLASSIFIER_LABEL_COUNT; i++) {
    if (result.classification[i].value > 0.8) {
      Serial.println(result.classification[i].label);
    }
  }
}

#include <zephyr/kernel.h>
