#include <zephyr/modbus/modbus.h>

const struct device *sht31 = DEVICE_DT_GET_ONE(sensirion_sht3xd);

uint16_t holding_regs[2];

static int read_sensor(void) {
  struct sensor_value temp, hum;
  sensor_sample_fetch(sht31);
  sensor_channel_get(sht31, SENSOR_CHAN_AMBIENT_TEMP, &temp);
  sensor_channel_get(sht31, SENSOR_CHAN_HUMIDITY, &hum);
  holding_regs[0] = (uint16_t)(temp.val1 * 100 + temp.val2 / 10000);
  holding_regs[1] = (uint16_t)(hum.val1 * 100 + hum.val2 / 10000);
  return 0;
}

void main(void) {
  while (1) {
    read_sensor();
    k_sleep(K_SECONDS(5));
  }
}
